from itertools import permutations

def is_derangement(p):
    # p is a tuple representing the permutation of {0, 1, ..., m-1}
    # Check if pi(i) != i for all i
    for i, val in enumerate(p):
        if val == i:
            return False
    return True

def sign(p):
    # p is a tuple representing the permutation of {0, 1, ..., m-1}
    # Count inversions
    m = len(p)
    inversions = 0
    for i in range(m):
        for j in range(i + 1, m):
            if p[i] > p[j]:
                inversions += 1
    # Sign is (-1)^inversions
    return 1 if inversions % 2 == 0 else -1

def calculate_S_m_sigma(m):
    elements = range(m)
    total_sum = 0
    derangement_count = 0

    # Generate all permutations
    all_perms = list(permutations(elements))

    for p in all_perms:
        if is_derangement(p):
            derangement_count += 1
            total_sum += sign(p)

    return total_sum, derangement_count

# Calculate for m=5
m5_sum, m5_count = calculate_S_m_sigma(5)
print(f"m=5: Sum S_5^sigma = {m5_sum}, Number of derangements = {m5_count}")

# Calculate for m=6
